import{_ as g,C as r,o as i,c as d,a3 as a,j as t,E as o,a as n,w as h}from"./chunks/framework.CCylkYel.js";const c="/screens/snapshots/arrange_queue.png",p="/screens/snapshots/arrange_picker.png",u="/screens/snapshots/arrange_playback.png",m="/screens/snapshots/arrange_queue_armed.png",b="/screens/snapshots/arrange.png",w="/screens/snapshots/arrange_hold_select.png",N=JSON.parse('{"title":"Arrange","description":"","frontmatter":{},"headers":[],"relativePath":"snapshots/lanes.md","filePath":"snapshots/lanes.md"}'),f={name:"snapshots/lanes.md"},k={tabindex:"0"};function S(T,e,A,E,R,y){const s=r("C"),l=r("ManualRelated");return i(),d("div",null,[e[14]||(e[14]=a('<h1 id="arrange" tabindex="-1">Arrange <a class="header-anchor" href="#arrange" aria-label="Permalink to &quot;Arrange&quot;">​</a></h1><p>Arrange is the <strong>song grid</strong> for stored snapshots: <strong>4–256 rows</strong> of time (default <strong>16</strong>) × 10 columns (Knobs, S32 LFOs, Rack 1–8). When the playhead lands on a row it recalls every occupied cell in that row (a scene). Empty cells are <strong>rest</strong> (<code>--</code>) and skip that bank. It is <strong>not</strong> a Step Seq MIDI device and does not sit in a rack.</p><p>Open <strong>ARRANGE</strong> from <a href="./../navigation/main-menu">Main Menu</a> — it is the <strong>first</strong> item, above Racks. The hub opens on the Knobs column. Rack, LFO, and snapshot grid nested menus do <strong>not</strong> have an Arrange shortcut.</p><p>The header title is <strong>ARRANGE</strong> (no timeline icon). Folder tabs <strong>SONG</strong> and a <strong>pencil</strong> sit left of the BPM band (never in it). The selected tab is a black tab with a thin outline that opens into the grid; the other one is plain gray text. The pencil is SETTINGS — the header never writes SETTINGS or SET. Two small gray squares with a dotted line under them, between the tabs and the BPM, mean <strong>Select + Back</strong> switches tabs. Hold Select for a moment on <strong>SONG</strong> and those squares become a bright circle and square (hold Select and turn to pick a column). A tap that never reached that hold still opens the cell picker; letting go after the column corners are showing does not. The BPM metronome in the header <strong>animates</strong> with the project clock.</p><h2 id="song-tab" tabindex="-1">SONG tab <a class="header-anchor" href="#song-tab" aria-label="Permalink to &quot;SONG tab&quot;">​</a></h2><p>All <strong>ten</strong> columns are on one page: <strong>K L R1 R2 R3 R4 R5 R6 R7 R8</strong>. Four song rows are visible; longer songs scroll so the focused cell stays in view. Occupied cells show two-digit slot ids <strong>01–32</strong>. Rest cells show a dim <code>--</code>. Row numbers on the left are three digits <strong>001–256</strong>. The cursor is four small corner marks at the focused cell. While the song plays, the <strong>playing row</strong> has its number on a gray block, and its occupied cells read brighter. When the clock is stopped or <strong>ARRANGE</strong> is <strong>OFF</strong>, no row is marked. A <strong>QUEUE-armed</strong> row&#39;s number block <strong>breathes</strong> (dims and brightens once per beat) until it fires or you cancel. A morphing bank’s column header is <code>K*</code> / <code>L*</code> / <code>R1*</code>…<code>R8*</code>. Column names are a <strong>legend</strong> (not an encoder stop).</p><p><img src="'+c+'" alt="Arrange with row 006 armed by QUEUE" class="screen"></p>',7)),t("table",k,[e[12]||(e[12]=t("thead",null,[t("tr",null,[t("th",null,"Control"),t("th",null,"SONG")])],-1)),t("tbody",null,[e[9]||(e[9]=t("tr",null,[t("td",null,"Encoder"),t("td",null,"Move the song row (001–LENGTH, clamped)")],-1)),e[10]||(e[10]=t("tr",null,[t("td",null,"Hold Select + encoder"),t("td",null,"Move columns (K … R8); stops at the ends, does not wrap. After a short hold the header mark becomes a circle and square, and the column corners appear even before you turn. Letting go after that hold does not open the cell picker.")],-1)),t("tr",null,[t("td",null,[o(s,{action:"select"}),e[0]||(e[0]=n()),e[1]||(e[1]=t("strong",null,"Select",-1))]),e[2]||(e[2]=t("td",null,[n("Open a cell picker: "),t("strong",null,"-- REST"),n(" first, then each stored snapshot ("),t("strong",null,"01 INTRO"),n(", "),t("strong",null,"02 VERSE"),n(", …). The rest of the screen dims; corner marks show your choice. Encoder does not wrap. Back cancels. Select applies. After the "),t("strong",null,"pencil"),n(" → "),t("strong",null,"SONG"),n(", the first Select still opens the picker.")],-1))]),t("tr",null,[t("td",null,[o(s,{action:"back-select"}),e[3]||(e[3]=n()),e[4]||(e[4]=t("strong",null,"Select + Back",-1))]),e[5]||(e[5]=t("td",null,[n("Switch to the "),t("strong",null,"pencil"),n(" tab (not zoom; not Select long-press)")],-1))]),e[11]||(e[11]=t("tr",null,[t("td",null,"Encoder click"),t("td",null,"Clock Start/Stop")],-1)),t("tr",null,[t("td",null,[o(s,{action:"back"}),e[6]||(e[6]=n()),e[7]||(e[7]=t("strong",null,"Back",-1))]),e[8]||(e[8]=t("td",null,"Leave Arrange",-1))])])]),e[15]||(e[15]=a('<p>The playing row follows the project clock. Start transport from the encoder button (Clock Start/Stop) or Clock Settings.</p><p><img src="'+p+'" alt="Arrange cell picker" class="screen"></p><h2 id="pencil-tab" tabindex="-1">Pencil tab <a class="header-anchor" href="#pencil-tab" aria-label="Permalink to &quot;Pencil tab&quot;">​</a></h2><p>A full-width list with the same <strong>13 px</strong> rows as other parameter lists (four visible; encoder scrolls): <strong>ARRANGE</strong>, <strong>RATE</strong>, <strong>FADE TIME</strong>, <strong>REPEAT</strong>, <strong>LENGTH</strong>, <strong>JUMP TO</strong>, <strong>QUEUE</strong>. Encoder moves between rows. The selected row is <strong>white text</strong> with the same corner marks as SONG. <strong>Hold Select</strong> makes the corners brighter and draws a line under the value, as wide as the longest value that row can show, so it does not move while you turn. Short <strong>Select</strong> on <strong>RATE</strong>, <strong>FADE TIME</strong>, <strong>REPEAT</strong>, or <strong>LENGTH</strong> latches sticky edit (a second set of corners inside the first, plus the same line; turn without holding Select). Tap Select again to keep the value; <strong>Back</strong> restores it — including the <strong>SONG</strong> / <strong>JUMP TO</strong> row if you had shortened <strong>LENGTH</strong>. Turn the encoder while holding Select to edit ARRANGE / RATE / FADE TIME / REPEAT / <strong>LENGTH</strong>, or to pick the SONG-focused row on <strong>JUMP TO</strong> (001–LENGTH, the same cursor as SONG). <strong>ARRANGE</strong> ON/OFF, <strong>REPEAT</strong>, <strong>RATE</strong>, <strong>FADE TIME</strong>, and <strong>LENGTH</strong> stop at the ends — they do not wrap. Hold Select on <strong>QUEUE</strong> does nothing. Select+Back returns to <strong>SONG</strong>. Back <strong>leaves Arrange</strong> (it does not return to SONG) unless sticky edit is open, in which case Back restores first. Encoder click is Clock Start/Stop.</p><p>Changing <strong>Rate</strong> while the arrangement is running keeps the current song row and the time already spent on it. If the new rate is longer (or shorter but you have not used up the new length yet), the row continues from those ticks. If the new rate is shorter and you are already past it, the playhead waits for the <strong>next bar</strong>, then moves once. Arrange <strong>Fade Time</strong> is only how the <strong>playhead</strong> glides in — pad / MIDI / <strong>SNAPSHOT</strong> macro glides use each bank’s own <strong>FADE TIME</strong>. It does not move the playhead.</p><p><strong>Arrange</strong> (the first pencil-tab row) is whether the arrangement <strong>runs</strong>. <strong>ON</strong> (default) lets the playhead, Jump To, and Queue recall snapshots. <strong>OFF</strong> freezes the playhead and ignores Jump / Queue; the SONG grid stays editable. Select tap toggles ON/OFF. Turning the encoder while holding Select moves toward ON or OFF and stops at the end — it does not wrap. Old projects load as <strong>ON</strong>.</p><p><strong>Rate</strong> is how long each row lasts against the project clock (24 PPQN):</p><table tabindex="0"><thead><tr><th>Rate</th><th>MIDI clocks</th></tr></thead><tbody><tr><td><strong>1 BAR</strong> (default)</td><td>96</td></tr><tr><td><strong>2 BARS</strong> … <strong>128 BARS</strong></td><td>96 × bars, including 3, 5, 6, 7, …</td></tr></tbody></table><p>Old projects that stored <strong>1/8</strong> or <strong>1/4</strong> load as <strong>1 BAR</strong>. <strong>Start</strong> fires row 0 immediately at every Rate. Rate is how long until the <strong>next</strong> row. Transport Start resets the playhead; Continue keeps it.</p><p><strong>Fade Time</strong> is how a playhead recall <strong>arrives</strong> (musical time at project BPM). The musical-time choices are unchanged. Jump To and Queue stay instant.</p><table tabindex="0"><thead><tr><th>Fade Time</th><th>Beats (4/4)</th></tr></thead><tbody><tr><td><strong>OFF</strong> (default)</td><td>Instant</td></tr><tr><td><strong>1/16</strong></td><td>0.25</td></tr><tr><td><strong>1/8</strong></td><td>0.5</td></tr><tr><td><strong>1/4</strong></td><td>1</td></tr><tr><td><strong>1/2</strong></td><td>2</td></tr><tr><td><strong>1 BAR</strong></td><td>4</td></tr><tr><td><strong>2 BARS</strong></td><td>8</td></tr><tr><td><strong>4 BARS</strong></td><td>16</td></tr></tbody></table><p><strong>Repeat</strong> is <strong>LOOP</strong> (wrap after the last filled row inside the current length) or <strong>ONCE</strong> (play to that row and stop).</p><p><strong>Length</strong> is how many song rows are active (<strong>4–256</strong>, default <strong>16</strong>). Hold Select + encoder. Shrinking the song does not erase hidden rows — lengthen again and they are still there. Jump, Queue, and the playhead stay inside the current length.</p><p><strong>Jump To</strong> fires the focused song row <strong>now</strong> (instant — bypasses Fade Time) and cancels Queue. <strong>Queue</strong> arms or cancels that same row for the <strong>next Rate boundary</strong> (also instant versus a playhead fade). Both are a <strong>single Select tap</strong>. They do nothing while <strong>ARRANGE</strong> is <strong>OFF</strong>. Queue reads <strong>ARMED</strong> or <strong>OFF</strong>, never a second row number. While Queue is <strong>ARMED</strong>, a small bar before that word <strong>breathes</strong> on the pencil tab (and the armed SONG row&#39;s number block breathes). Jump To snaps an in-progress fade to its target; Queue cancels the fade without snapping. Queue still works after <strong>ONCE</strong> has already stopped.</p><p><img src="'+u+'" alt="Arrange pencil tab, RATE in sticky edit" class="screen"></p><p><img src="'+m+'" alt="QUEUE ARMED on the pencil tab" class="screen"></p><p>When a row fires:</p><ul><li><strong>Rest</strong> (<code>--</code>) or an empty slot — that column is skipped.</li><li>Occupied slot <strong>different</strong> from the one already active — recall that snapshot (playhead uses Fade Time; Jump To and Queue are instant). While a glide runs on that bank, “active” is the pad it is gliding to. Any other occupied pad turns the glide toward that pad, starting from the live sound. That includes the pad the glide is leaving.</li><li>Same slot as now — no second recall.</li><li>A <strong>MORPH</strong> knob turned up on that bank does not hold the column back. The step takes over like a pad recall, and the knob picks up from the new percent. It reads <strong>0%</strong> once the step lands.</li><li>Other columns in the row still fire.</li></ul><p>Arrange edits and recalls do <strong>not</strong> force a flash save. Use <a href="./../projects/">Save Project</a> so the pattern survives power-off.</p><p><img src="'+b+'" alt="Arrange hub" class="screen"></p><p>Hold Select for a moment (not a tap) on <strong>SONG</strong>: the header mark becomes a circle and square, bright corners mark the whole current column (the cell corners go away), and the other columns dim before you turn. Letting go then does not open the cell picker.</p><p><img src="'+w+'" alt="Arrange hold Select column" class="screen"></p>',22)),o(l,null,{default:h(()=>[...e[13]||(e[13]=[t("ul",null,[t("li",null,[t("a",{href:"./"},"Snapshots"),n(" — Snapshot overview")]),t("li",null,[t("a",{href:"./studio"},"Open a snapshot bank"),n(" — One door per bank")]),t("li",null,[t("a",{href:"./knob-bank"},"Knob snapshots"),n(" — snapshot grid from Main Menu → Snapshots")]),t("li",null,[t("a",{href:"./rack-bank"},"Rack snapshots"),n(" — Live rack bank")]),t("li",null,[t("a",{href:"./lfo-bank"},"LFO snapshots"),n(" — Live LFO bank")]),t("li",null,[t("a",{href:"./morph"},"Morph"),n(" — Live to a pad; this bank's FADE TIME is the pad recall glide")]),t("li",null,[t("a",{href:"./../settings/"},"Settings"),n(" — Clock Settings (transport and BPM)")])],-1)])]),_:1})])}const v=g(f,[["render",S]]);export{N as __pageData,v as default};
